  2806          case CIL_NEQ:
  2807          case CIL_CONS_DOM:
  2808          case CIL_CONS_DOMBY:
  2809          case CIL_CONS_INCOMP:
  2810                  rc = __cil_fill_constraint_leaf_expr(current, flavor, op, expr);
